// Assemble scripts/ocr/gemm.wat into src/ocr/gemm-wasm.js (the module's bytes as base64, plus the
// SHA-256 of the source it came from). R&D tool: needs the wabt package outside the repo; the
// extension ships only the generated bytes, which are CMMNS' own code.
//
//   WABT_DIR=.../node_modules/wabt node scripts/ocr/build-wasm.mjs
import { readFileSync, writeFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { join, dirname } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const here = dirname(fileURLToPath(import.meta.url)), root = join(here, "../..");
const wabt = await (await import(pathToFileURL(join(process.env.WABT_DIR, "index.js")).href)).default();
const src = readFileSync(join(here, "gemm.wat"), "utf8").replace(/\r\n/g, "\n");
const mod = wabt.parseWat("gemm.wat", src, { simd: true });
mod.validate();
const { buffer } = mod.toBinary({});
const b64 = Buffer.from(buffer).toString("base64");
const sha = createHash("sha256").update(src).digest("hex");
writeFileSync(join(root, "src/ocr/gemm-wasm.js"), `// Generated by scripts/ocr/build-wasm.mjs from scripts/ocr/gemm.wat. Do not edit.
// The WebAssembly SIMD matrix product for the text recogniser (${buffer.length} bytes).
export const GEMM_WAT_SHA256 = "${sha}";
export const GEMM_WASM = "${b64}";
`);
console.log(`gemm-wasm.js: ${buffer.length} bytes of WebAssembly`);
